struct Circle { var radius: Double }            // value type: assignment copies

var a = Circle(radius: 1)
var b = a; b.radius = 2                          // a.radius is still 1

final class Document: NSCopying {                // reference type: explicit copy
    var title: String
    init(title: String) { self.title = title }
    func copy(with zone: NSZone? = nil) -> Any { Document(title: title) }
}

